<template><view class="page"><view class="head" @tap="back">‹ <b>设置</b></view><view class="group"><view v-for="x in items" :key="x.type" class="item" @tap="notice(x)">{{x.name}} <text>›</text></view></view><button @tap="logout">退出登录</button><view class="tip">{{tip}}</view></view></template><script setup>import{ref}from'vue';const items=[{name:'编辑个人资料',type:'edit'},{name:'账号与安全',type:'account'},{name:'隐私设置',type:'privacy'},{name:'消息通知',type:'notifications'},{name:'黑名单',type:'blacklist'},{name:'通用设置',type:'general'},{name:'用户协议与隐私政策',type:'agreement'},{name:'关于我们',type:'about'}];const tip=ref('');function back(){uni.navigateBack()}function notice(x){uni.navigateTo({url:'/pages/feature/index?type='+encodeURIComponent(x.type)},fail:()=>{tip.value='页面打开失败，请返回重试'}})}function logout(){uni.reLaunch({url:'/pages/auth/index'})}</script><style scoped lang="scss">.page{min-height:100vh;background:#f7f5fa;color:#373142;padding:20px 16px}.head{font-size:28px;margin:12px 4px 24px}.head b{font-size:18px;margin-left:18px}.group{background:white;border-radius:18px;padding:0 16px}.item{height:54px;display:flex;align-items:center;justify-content:space-between;border-bottom:1px solid #f4f1f6;font-size:14px}.item:last-child{border:0}.item text{color:#bbb;font-size:22px}button{margin-top:28px;border:0;border-radius:24px;background:white;color:#df77a9;font-size:14px}.tip{text-align:center;color:#aaa;font-size:11px;margin-top:16px}</style>